import assert from 'assert';
import {randomBytes} from 'crypto';
globalThis.crypto={randomUUID:()=>randomBytes(16).toString('hex')};
import {example,parseDraft,generate} from './model.js';
import {emptyModel,validateModel,updateHints,tableCaption,columnCaption,formatHintLines,parseHintLines} from './model-hints.js';
const relation={schema:'sales',name:'orders'},column={name:'status',data_type:'text'};
const model=updateHints(emptyModel(),relation,column,{label:'Заказы',description:'Описание'},{label:'Статус',values:[{value:'new',label:'Новый'}]});
assert.equal(tableCaption(model,relation),'Заказы - orders');assert.equal(columnCaption(model,relation,column),'Статус - status: text');
assert.equal(tableCaption(model,{schema:'other',name:'orders'}),'orders');
const project=example();project.model=JSON.parse(JSON.stringify(model));assert.deepEqual(parseDraft(JSON.stringify(project)),{...project,model:{...model,tables:model.tables.map(t=>({...t,columns:t.columns.map(c=>({...c,description:''}))}))}});
console.log('PASS model hints: project round trip and exact names');
const legacy={...example(),schemaVersion:1};delete legacy.model;
const upgraded=parseDraft(JSON.stringify(legacy));assert.equal(upgraded.schemaVersion,3);assert.deepEqual(upgraded.model,emptyModel());assert.equal(generate(legacy).sql,generate(upgraded).sql);
console.log('PASS model hints: legacy migration preserves generated SQL');
const copy=()=>JSON.parse(JSON.stringify(model));
let invalid=copy();invalid.tables.push(invalid.tables[0]);assert.throws(()=>validateModel(invalid));
invalid=copy();invalid.tables[0].columns[0].values.push({value:'new',label:'Повтор'});assert.throws(()=>validateModel(invalid));
invalid=copy();invalid.tables[0].columns[0].sql='DROP TABLE data';assert.throws(()=>validateModel(invalid));
invalid=copy();invalid.tables[0].name='x\0';assert.throws(()=>validateModel(invalid));
invalid=copy();invalid.name='я'.repeat(65);assert.throws(()=>validateModel(invalid));
assert.throws(()=>validateModel(JSON.parse('{"name":"x","tables":[],"__proto__":{"polluted":true}}')));
console.log('PASS model hints: duplicates, byte limits and unknown fields rejected');
const before=generate(project).sql;project.model.tables[0].label='<img src=x onerror=alert(1)>';assert.equal(generate(project).sql,before);assert.equal(model.tables[0].label,'Заказы');
console.log('PASS model hints: labels never change SQL or mutate previous settings');
const values=[{value:'new',label:'Новый'},{value:' a|b\n',label:'Подпись\nс переносом'},{value:'',label:''},{value:'[abc',label:'Скобка'}];
assert.deepEqual(parseHintLines(formatHintLines(values)),values);assert.throws(()=>parseHintLines('[null,"label"]'));assert.throws(()=>parseHintLines('value without separator'));
console.log('PASS model hints: value editor preserves separators, newlines and empty strings');
